"use client";

import Image from "next/image";
import Link from "next/link";
import { createContext, useCallback, useContext, useEffect, useRef, useState, useTransition } from "react";
import { CheckCircle2, Info, ShoppingBag, Trash2, X, XCircle } from "lucide-react";
import { getMiniCart, removeCartItem, type MiniCart } from "@/app/actions/cart";
import { getWishlistIds, toggleWishlist } from "@/app/actions/wishlist";
import { useRouter } from "next/navigation";
import { formatINR } from "@/lib/money";
import { SHIPPING } from "@/lib/site";

type Toast = { id: number; kind: "success" | "error" | "info"; text: string; action?: { label: string; href: string } };

type StoreUI = {
  toast: (text: string, kind?: Toast["kind"], action?: Toast["action"]) => void;
  openCart: () => void;
  /** Animate a product image flying into the header cart icon. */
  flyToCart: (from: HTMLElement | null) => void;
  wishlist: Set<string>;
  toggleWish: (productId: string, name: string) => Promise<void>;
};

const Ctx = createContext<StoreUI | null>(null);

export function useStoreUI() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useStoreUI must be used inside <StoreUIProvider>");
  return ctx;
}

function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function StoreUIProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [cartOpen, setCartOpen] = useState(false);
  const seq = useRef(0);
  const router = useRouter();
  const [wishlist, setWishlist] = useState<Set<string>>(new Set());

  useEffect(() => {
    getWishlistIds().then((ids) => setWishlist(new Set(ids))).catch(() => {});
  }, []);

  const toast = useCallback<StoreUI["toast"]>((text, kind = "success", action) => {
    const id = ++seq.current;
    setToasts((t) => [...t.slice(-2), { id, kind, text, action }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3800);
  }, []);

  const flyToCart = useCallback<StoreUI["flyToCart"]>((from) => {
    const target = document.querySelector<HTMLElement>("[data-cart-target]:not([hidden])");
    const img = from?.querySelector("img") ?? (from instanceof HTMLImageElement ? from : null);
    if (!img || !target || prefersReducedMotion()) return;
    const a = img.getBoundingClientRect();
    const b = target.getBoundingClientRect();
    if (!a.width || !b.width) return;
    const ghost = img.cloneNode(true) as HTMLImageElement;
    Object.assign(ghost.style, {
      position: "fixed", left: `${a.left}px`, top: `${a.top}px`, width: `${a.width}px`, height: `${a.height}px`,
      objectFit: "contain", zIndex: "80", pointerEvents: "none", borderRadius: "12px", background: "white",
      boxShadow: "0 10px 30px rgb(0 0 0 / 0.2)",
    });
    document.body.appendChild(ghost);
    const dx = b.left + b.width / 2 - (a.left + a.width / 2);
    const dy = b.top + b.height / 2 - (a.top + a.height / 2);
    ghost
      .animate(
        [
          { transform: "translate(0,0) scale(1)", opacity: 1 },
          { transform: `translate(${dx * 0.6}px, ${dy * 0.35 - 80}px) scale(0.45)`, opacity: 0.95, offset: 0.55 },
          { transform: `translate(${dx}px, ${dy}px) scale(0.08)`, opacity: 0.4 },
        ],
        { duration: 750, easing: "cubic-bezier(0.5, 0, 0.3, 1)" },
      )
      .finished.finally(() => ghost.remove());
  }, []);

  const toggleWish = useCallback<StoreUI["toggleWish"]>(
    async (productId, name) => {
      // Optimistic update; rolled back if the server refuses.
      const had = wishlist.has(productId);
      setWishlist((w) => { const n = new Set(w); if (had) n.delete(productId); else n.add(productId); return n; });
      const res = await toggleWishlist(productId);
      if (!res.ok) {
        setWishlist((w) => { const n = new Set(w); if (had) n.add(productId); else n.delete(productId); return n; });
        if (res.needsLogin) {
          toast("Sign in to save items to your wishlist", "info", { label: "Sign in", href: `/login?next=${encodeURIComponent(location.pathname)}` });
        } else toast(res.error ?? "Could not update wishlist", "error");
        return;
      }
      toast(res.saved ? `Saved “${name}” to your wishlist` : "Removed from wishlist", res.saved ? "success" : "info", res.saved ? { label: "View", href: "/account/wishlist" } : undefined);
      router.refresh();
    },
    [wishlist, toast, router],
  );

  return (
    <Ctx value={{ toast, openCart: () => setCartOpen(true), flyToCart, wishlist, toggleWish }}>
      {children}
      <CartDrawer open={cartOpen} onClose={() => setCartOpen(false)} />
      <div className="pointer-events-none fixed inset-x-0 bottom-20 z-[70] flex flex-col items-center gap-2 px-4 sm:bottom-6" aria-live="polite">
        {toasts.map((t) => (
          <div key={t.id} role="status" className="animate-toast-in pointer-events-auto flex w-full max-w-sm items-center gap-3 rounded-lg bg-ink px-4 py-3 text-sm text-white shadow-xl">
            {t.kind === "success" ? <CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-400" aria-hidden /> : t.kind === "error" ? <XCircle className="h-5 w-5 shrink-0 text-red-400" aria-hidden /> : <Info className="h-5 w-5 shrink-0 text-brass-light" aria-hidden />}
            <span className="flex-1">{t.text}</span>
            {t.action && <Link href={t.action.href} className="font-semibold text-brass-light hover:underline">{t.action.label}</Link>}
          </div>
        ))}
      </div>
    </Ctx>
  );
}

function CartDrawer({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [cart, setCart] = useState<MiniCart | null>(null);
  const [pending, start] = useTransition();

  useEffect(() => {
    if (!open) return;
    start(async () => setCart(await getMiniCart()));
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [open, onClose]);

  if (!open) return null;
  const toFree = cart ? Math.max(0, SHIPPING.freeAbove - cart.subtotal) : 0;
  const progress = cart ? Math.min(100, (cart.subtotal / SHIPPING.freeAbove) * 100) : 0;

  return (
    <div className="fixed inset-0 z-[60]" role="dialog" aria-modal="true" aria-label="Your cart">
      <div className="animate-fade-in absolute inset-0 bg-black/45" onClick={onClose} />
      <aside className="animate-slide-in-right absolute right-0 top-0 flex h-full w-full max-w-md flex-col bg-white shadow-2xl">
        <div className="flex items-center justify-between border-b border-line px-5 py-4">
          <p className="flex items-center gap-2 font-display text-xl font-semibold"><ShoppingBag className="h-5 w-5 text-brass" aria-hidden /> Your cart {cart && <span className="text-sm font-normal text-muted">({cart.count})</span>}</p>
          <button onClick={onClose} aria-label="Close cart" className="press rounded-full p-1.5 hover:bg-paper"><X className="h-5 w-5" /></button>
        </div>
        {cart && cart.items.length > 0 && (
          <div className="border-b border-line px-5 py-3 text-sm">
            {toFree > 0 ? <p>Add <b>{formatINR(toFree)}</b> more for <span className="font-semibold text-success">FREE delivery</span></p> : <p className="font-semibold text-success">🎉 You’ve unlocked FREE delivery</p>}
            <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-line"><div className="h-full rounded-full bg-success transition-[width] duration-700" style={{ width: `${progress}%` }} /></div>
          </div>
        )}
        <div className="flex-1 overflow-y-auto px-5">
          {!cart && <div className="space-y-3 py-5">{[0, 1, 2].map((i) => <div key={i} className="skeleton h-20 rounded-lg" />)}</div>}
          {cart && cart.items.length === 0 && <p className="py-16 text-center text-sm text-muted">Your cart is empty.</p>}
          <ul className="divide-y divide-line">
            {cart?.items.map((it, i) => (
              <li key={it.id} className="animate-fade-up flex gap-3 py-4" style={{ animationDelay: `${i * 50}ms` }}>
                <Link href={`/product/${it.slug}`} onClick={onClose} className="relative h-20 w-20 shrink-0 rounded-md bg-paper">
                  {it.image && <Image src={it.image} alt="" fill sizes="80px" className="object-contain p-1.5" />}
                </Link>
                <div className="flex-1 text-sm">
                  <Link href={`/product/${it.slug}`} onClick={onClose} className="line-clamp-2 font-medium hover:text-maroon">{it.name}</Link>
                  {it.engravingText && <p className="text-xs text-brass">Engraving: “{it.engravingText}”</p>}
                  <p className="mt-1 text-muted">Qty {it.quantity} · <span className="font-semibold text-ink">{formatINR(it.price * it.quantity)}</span></p>
                </div>
                <button
                  disabled={pending}
                  onClick={() => start(async () => { await removeCartItem(it.id); setCart(await getMiniCart()); })}
                  aria-label={`Remove ${it.name}`}
                  className="press self-start rounded p-1 text-muted hover:text-danger"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </li>
            ))}
          </ul>
        </div>
        {cart && cart.items.length > 0 && (
          <div className="space-y-2 border-t border-line p-5">
            <p className="flex justify-between text-lg"><span>Subtotal</span><span className="font-semibold">{formatINR(cart.subtotal)}</span></p>
            <Link href="/checkout" onClick={onClose} className="btn-brass press w-full rounded-full py-3">Proceed to checkout</Link>
            <Link href="/cart" onClick={onClose} className="btn-outline press w-full rounded-full">View full cart</Link>
          </div>
        )}
      </aside>
    </div>
  );
}
